output_text:
[
  {
    "id": "must_take_cart",
    "text": "A shopper is obliged to take the available cart before continuing the shopping trip.",
    "abstraction": {
      "state_properties": {
        "start_cart_station": "cartAt(1,5)"
      },
      "events": {
        "cart_taken": {
          "pre": {
            "and": [
              "at(1,5)",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "cart_taken"
    }
  },
  {
    "id": "items_only_with_cart",
    "text": "A shopper is prohibited from picking up shelf items unless they are currently pushing the cart.",
    "abstraction": {
      "state_properties": {
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "item_pickup_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "item_pickup_without_cart"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "A shopper is prohibited from carrying groceries by hand rather than using the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_by_hand"
    }
  },
  {
    "id": "return_cart_to_bay",
    "text": "After taking a cart, the shopper is obliged to return it to the cart-return bay at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)",
        "cart_parked_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "cart_taken": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "cart_returned": {
          "pre": {
            "and": [
              "cart_return_bay",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_taken",
      "discharge": "cart_returned"
    }
  },
  {
    "id": "only_drop_cart_at_return_bay",
    "text": "A shopper is prohibited from leaving the cart anywhere except the designated return bay at (0,1).",
    "abstraction": {
      "state_properties": {
        "at_cart_return_bay": "at(0,1)",
        "not_at_cart_return_bay": {
          "not": "at_cart_return_bay"
        }
      },
      "events": {
        "cart_dropped_elsewhere": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "not_at_cart_return_bay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_dropped_elsewhere"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "A shopper is prohibited from exiting the store while still holding or pushing the cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart"
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "EXIT",
              "pushing_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart"
    }
  },
  {
    "id": "cart_forbidden_in_exit_zone",
    "text": "Carts are prohibited in the right-side pedestrian exit zone, so shoppers must leave the cart before travelling there.",
    "abstraction": {
      "state_properties": {
        "right_side_exit_zone": {
          "or": [
            "at(7,0)",
            "at(7,1)",
            "at(7,2)",
            "at(7,3)",
            "at(7,4)",
            "at(7,5)",
            "at(8,0)",
            "at(8,1)",
            "at(8,2)",
            "at(8,3)",
            "at(8,4)",
            "at(8,5)",
            "at(9,0)",
            "at(9,1)",
            "at(9,2)",
            "at(9,3)",
            "at(9,4)",
            "at(9,5)"
          ]
        },
        "cart_in_exit_zone": {
          "and": [
            "hasCart",
            "right_side_exit_zone"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_in_exit_zone"
    }
  },
  {
    "id": "no_east_past_endcap_with_cart",
    "text": "When pushing a cart at the eastern end of a shopping aisle, the shopper is prohibited from continuing east past the endcap.",
    "abstraction": {
      "state_properties": {
        "east_aisle_endcap": {
          "or": [
            "at(6,2)",
            "at(6,4)"
          ]
        },
        "pushing_cart_at_endcap": {
          "and": [
            "hasCart",
            "east_aisle_endcap"
          ]
        }
      },
      "events": {
        "push_cart_east_past_endcap": {
          "pre": {
            "and": [
              "pushing_cart_at_endcap",
              "E"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "push_cart_east_past_endcap"
    }
  }
]
